// Trust anchors for the launcher's TLS client.
//
// Primary source: the Windows "ROOT" system store, read with CryptoAPI
// (CertOpenSystemStoreW + CertEnumCertificatesInStore, both present since
// Windows 2000), so we honour whatever roots the machine trusts, including
// corporate ones and roots delivered by Windows Update.
//
// Fallback: a bundled Mozilla root set (ca_bundle_mozilla.inc, generated by
// tools/gen_ca_bundle.py with its provenance and date in the header). It is
// the primary set when the store yields nothing usable, and the second try
// when a handshake fails with "issuer not trusted": Windows 7 installs most
// roots lazily (CryptoAPI fetches them during its own chain building), which
// a non-CryptoAPI TLS stack never triggers, so a stock Win7 store routinely
// lacks e.g. ISRG Root X1 (Let's Encrypt).
//
// FM2K_CA_FILE=<path> (PEM or DER) adds anchors to both sets, for testing
// against a local server with a private CA. It is logged loudly every time.
// Verification itself is never disabled.

#include "ca_store.h"
#include "tls_internal.h"

#include <SDL3/SDL_log.h>

#include <cstdio>
#include <cstdlib>
#include <mutex>
#include <string>
#include <vector>

#if defined(_WIN32)
#  include <windows.h>
#  include <wincrypt.h>
#endif

namespace fm2k::net::tls {

namespace {

#include "ca_bundle_mozilla.inc"

struct AnchorState {
    mbedtls_x509_crt primary;
    mbedtls_x509_crt with_bundle;
    CaStoreStats     stats;
};

std::once_flag g_once;
AnchorState*   g_state = nullptr;   // immortal: TLS may run during static teardown

int AddDer(mbedtls_x509_crt* chain, const unsigned char* der, size_t len) {
    return mbedtls_x509_crt_parse_der(chain, der, len) == 0 ? 1 : 0;
}

// Returns DER blobs of every certificate in the system ROOT store.
std::vector<std::vector<unsigned char>> ReadSystemRoots(int& seen) {
    std::vector<std::vector<unsigned char>> out;
    seen = 0;
#if defined(_WIN32)
    HCERTSTORE store = CertOpenSystemStoreW(0, L"ROOT");
    if (!store) {
        SDL_LogWarn(SDL_LOG_CATEGORY_APPLICATION,
                    "TLS: CertOpenSystemStore(ROOT) failed (err=%lu)",
                    (unsigned long)GetLastError());
        return out;
    }
    PCCERT_CONTEXT ctx = nullptr;
    while ((ctx = CertEnumCertificatesInStore(store, ctx)) != nullptr) {
        ++seen;
        if ((ctx->dwCertEncodingType & X509_ASN_ENCODING) == 0) continue;
        out.emplace_back(ctx->pbCertEncoded, ctx->pbCertEncoded + ctx->cbCertEncoded);
    }
    CertCloseStore(store, 0);
#else
    // Portable path for a future native Linux build: the distro bundle.
    for (const char* path : {"/etc/ssl/certs/ca-certificates.crt",
                             "/etc/pki/tls/certs/ca-bundle.crt"}) {
        FILE* f = std::fopen(path, "rb");
        if (!f) continue;
        std::vector<unsigned char> pem;
        unsigned char buf[8192];
        size_t n;
        while ((n = std::fread(buf, 1, sizeof(buf), f)) > 0) pem.insert(pem.end(), buf, buf + n);
        std::fclose(f);
        pem.push_back(0);
        out.push_back(std::move(pem));   // one PEM blob; parsed as a bundle below
        seen = 1;
        break;
    }
#endif
    return out;
}

int ChainLength(const mbedtls_x509_crt* chain) {
    int n = 0;
    for (const mbedtls_x509_crt* c = chain; c && c->raw.len; c = c->next) ++n;
    return n;
}

// Adds one DER certificate or a PEM bundle; returns how many were accepted.
int AddPemOrDerBlob(mbedtls_x509_crt* chain, std::vector<unsigned char> blob) {
    if (blob.empty()) return 0;
    const bool pem = std::string(blob.begin(), blob.end()).find("-----BEGIN") != std::string::npos;
    if (!pem) return AddDer(chain, blob.data(), blob.size());
    if (blob.back() != 0) blob.push_back(0);
    const int before = ChainLength(chain);
    mbedtls_x509_crt_parse(chain, blob.data(), blob.size());   // >0 = some failed; keep the rest
    return ChainLength(chain) - before;
}

std::vector<unsigned char> ReadFile(const char* path) {
    std::vector<unsigned char> data;
    FILE* f = std::fopen(path, "rb");
    if (!f) return data;
    unsigned char buf[8192];
    size_t n;
    while ((n = std::fread(buf, 1, sizeof(buf), f)) > 0) data.insert(data.end(), buf, buf + n);
    std::fclose(f);
    return data;
}

void Load() {
    g_state = new AnchorState();
    mbedtls_x509_crt_init(&g_state->primary);
    mbedtls_x509_crt_init(&g_state->with_bundle);
    CaStoreStats& st = g_state->stats;
    st.bundle_date = kMozillaRootsDate;

    int seen = 0;
    auto roots = ReadSystemRoots(seen);
    st.store_seen = seen;
    for (auto& der : roots) {
        const int a = AddPemOrDerBlob(&g_state->primary, der);
        AddPemOrDerBlob(&g_state->with_bundle, std::move(der));
        st.store_parsed += a;
    }

    for (const auto& r : kMozillaRoots) {
        st.bundle_parsed += AddDer(&g_state->with_bundle, r.der, r.len);
    }
    if (st.store_parsed == 0) {
        st.primary_is_bundle = true;
        for (const auto& r : kMozillaRoots) AddDer(&g_state->primary, r.der, r.len);
    }

    if (const char* extra = std::getenv("FM2K_CA_FILE"); extra && *extra) {
        std::vector<unsigned char> blob = ReadFile(extra);
        st.extra_parsed = AddPemOrDerBlob(&g_state->primary, blob);
        AddPemOrDerBlob(&g_state->with_bundle, std::move(blob));
        SDL_LogWarn(SDL_LOG_CATEGORY_APPLICATION,
                    "TLS: *** FM2K_CA_FILE is set: trusting %d EXTRA certificate(s) from "
                    "\"%s\" for every HTTPS/WSS connection. Unset it unless you are "
                    "testing against a private server. ***",
                    st.extra_parsed, extra);
    }

    SDL_LogInfo(SDL_LOG_CATEGORY_APPLICATION,
                "TLS: trust anchors -- Windows ROOT store %d/%d usable, bundled Mozilla "
                "set %d (data as of %s)%s",
                st.store_parsed, st.store_seen, st.bundle_parsed, kMozillaRootsDate,
                st.primary_is_bundle ? "; store empty, using the bundled set" : "");
}

}  // namespace

mbedtls_x509_crt* TrustAnchors(Anchors which) {
    std::call_once(g_once, Load);
    return which == Anchors::Primary ? &g_state->primary : &g_state->with_bundle;
}

CaStoreStats GetCaStoreStats() {
    std::call_once(g_once, Load);
    return g_state->stats;
}

}  // namespace fm2k::net::tls
